local({
  mother <- coalesce(as.numeric(B01P06), as.numeric(B01006), as.numeric(VB01006))
  father <- coalesce(as.numeric(B01P07), as.numeric(B01007), as.numeric(VB01007))
  case_when(
    mother == 1 & father == 1 ~ "Two biological/adoptive parents",
    (mother == 1 & father == 2) | (mother == 2 & father == 1) ~ "Single parent",
    mother == 2 & father == 2 ~ "Other",
    .default = "Unknown"
  )
})

local({
  frequency <- coalesce(as.numeric(B06P04), as.numeric(B07007), as.numeric(VB07007))
  count <- coalesce(as.numeric(B07007A), as.numeric(B07007B))
  case_when(frequency == 1 ~ "FALSE", frequency %in% 2:5 ~ "TRUE", count == 1 ~ "FALSE", count %in% 2:4 ~ "TRUE")
})

local({
  count_12m <- coalesce(as.numeric(B09011), as.numeric(VB09011))
  any_30d <- coalesce(as.numeric(B08P04), as.numeric(B09011A))
  case_when(count_12m == 1 ~ "FALSE", count_12m %in% 2:8 ~ "TRUE", any_30d == 1 ~ "TRUE", any_30d == 2 ~ "FALSE")
})

local({
  vomit <- coalesce(as.numeric(B10P03), as.numeric(B11003), as.numeric(VB11003))
  pills <- coalesce(as.numeric(B10P04), as.numeric(B11004), as.numeric(VB11004A), as.numeric(B11004A))
  case_when(vomit %in% 1 | pills %in% 1 ~ "TRUE", vomit %in% 2 | pills %in% 2 ~ "FALSE")
})

local({
  code <- coalesce(as.numeric(B03011), as.numeric(VB03011A))
  if_else(code %in% 1:8, code - 1, NA_real_)
})
